    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        if len(text2) > len(text1):
            text1, text2 = text2, text1
        dp = [0] * (len(text2) + 1)
        for ch in text1:
            diag = 0  # dp[i-1][j-1]
            for j in range(1, len(text2) + 1):
                above = dp[j]
                dp[j] = diag + 1 if ch == text2[j - 1] else max(above, dp[j - 1])
                diag = above
        return dp[-1]
