        dp = [[1] + [0] * amount for _ in range(n + 1)]
        for i in range(1, n + 1):
            c = coins[i - 1]
            for a in range(1, amount + 1):
                dp[i][a] = dp[i - 1][a] + (dp[i][a - c] if c <= a else 0)
        return dp[n][amount]
