            return False

        @cache
        def ok(i: int, j: int) -> bool:
            if i == len(s1) and j == len(s2):
                return True
            want = s3[i + j]
            return (i < len(s1) and s1[i] == want and ok(i + 1, j)) or \
                   (j < len(s2) and s2[j] == want and ok(i, j + 1))

        return ok(0, 0)
```

**Time:** O(n·m)
