    def numDistinct(self, s: str, t: str) -> int:
        m = len(t)
        dp = [0] * m + [1]
        for ch in reversed(s):
            for j in range(m):  # left to right: dp[j+1] is still last row's value
                if ch == t[j]:
                    dp[j] += dp[j + 1]
        return dp[0]
