    def minDistance(self, word1: str, word2: str) -> int:
        m = len(word2)
        dp = list(range(m + 1))
        for i in range(1, len(word1) + 1):
            diag, dp[0] = dp[0], i  # diag = old dp[i-1][j-1]
            for j in range(1, m + 1):
                above = dp[j]
                if word1[i - 1] == word2[j - 1]:
                    dp[j] = diag
                else:
                    dp[j] = 1 + min(diag, above, dp[j - 1])
                diag = above
        return dp[m]
