    def maxCoins(self, nums: List[int]) -> int:
        vals = [1] + nums + [1]

        @cache
        def best(l: int, r: int) -> int:  # balloons strictly between l and r
            return max((best(l, k) + vals[l] * vals[k] * vals[r] + best(k, r)  # k burst last
                        for k in range(l + 1, r)), default=0)

        return best(0, len(vals) - 1)
```

**Time:** O(n³): n² intervals × n choices of `k`
**Space:** O(n²)
:::

:::details 2. Bottom-up interval DP
Fill `dp[l][r]` by increasing gap `r − l` so that both sub-intervals are already known. The answer is `dp[0][n+1]`.

**Java**

```java
class Solution {
    public int maxCoins(int[] nums) {
        int n = nums.length;
        int[] vals = new int[n + 2];
        vals[0] = vals[n + 1] = 1;
        for (int i = 0; i < n; i++) vals[i + 1] = nums[i];
        int[][] dp = new int[n + 2][n + 2];
        for (int gap = 2; gap <= n + 1; gap++)
            for (int l = 0; l + gap <= n + 1; l++) {
                int r = l + gap;
                for (int k = l + 1; k < r; k++)
                    dp[l][r] = Math.max(dp[l][r], dp[l][k] + vals[l] * vals[k] * vals[r] + dp[k][r]);
            }
        return dp[0][n + 1];
    }
}
```

